import { SongReference } from './song-reference.entity';

/**
 * A schedule reference auto-generated by the app (e.g. a Spotify playlist
 * created from a schedule). Extends SongReference with sync metadata that
 * tracks the state of the generated artifact. Persisted as part of the
 * `schedules."references"` JSON column.
 */
export class SchedulePlaylistReference extends SongReference {
  /** Which app feature generated this reference. */
  source!: 'spotify-auto' | 'youtube-auto';
  syncedAt?: string;
  tracksHash?: string;
  syncedBy?: number;
  syncedByName?: string;

  syncedByMe?: boolean;
}
